import{_ as e,o as a,c as i,ao as r}from"./chunks/framework.DdhParCf.js";const g=JSON.parse('{"title":"Examples","description":"","frontmatter":{},"headers":[],"relativePath":"examples.md","filePath":"examples.md","lastUpdated":null}'),n={name:"examples.md"};function s(l,t,d,o,p,c){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="Examples" tabindex="-1">Examples <a class="header-anchor" href="#Examples" aria-label="Permalink to &quot;Examples {#Examples}&quot;">​</a></h1><p>These recipes model complete devices. Start with the <a href="./quickstart">quickstart</a> for a small first calculation. Each recipe lists its dependencies and draws its circuit: <code>[x]</code> is the component named <code>x</code> in the code, <code>||</code> joins components in parallel, and node <code>0</code> is ground.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Example</th><th style="text-align:right;">What it calculates</th></tr></thead><tbody><tr><td style="text-align:right;"><a href="./recipes/jpa">Josephson parametric amplifier (JPA)</a></td><td style="text-align:right;">The reflection gain of a current-pumped JPA, against WRspice</td></tr><tr><td style="text-align:right;"><a href="./recipes/environment">JPA with a frequency dependent environmental impedance</a></td><td style="text-align:right;">The same JPA through a cable from a mismatched source, the pump-off reflection against a closed form</td></tr><tr><td style="text-align:right;"><a href="./recipes/multitone">Multi-tone Fourier grids</a></td><td style="text-align:right;">The retained modes and evaluation grids of one, two and three pump tones, and their refinement</td></tr><tr><td style="text-align:right;"><a href="./recipes/double-pump">Double-pumped JPA</a></td><td style="text-align:right;">The gain between two pump tones, against WRspice</td></tr><tr><td style="text-align:right;"><a href="./recipes/flux-pump">Flux-pumped JPA</a></td><td style="text-align:right;">Three-wave mixing in a flux-biased SQUID, against WRspice, and the resonance against the bias</td></tr><tr><td style="text-align:right;"><a href="./recipes/snail">SNAIL parametric amplifier</a></td><td style="text-align:right;">Pump-on and pump-off gain near a Kerr-free point, against WRspice</td></tr><tr><td style="text-align:right;"><a href="./recipes/traveling-wave">Josephson traveling wave parametric amplifier (JTWPA)</a></td><td style="text-align:right;">Gain, idlers, quantum efficiency and commutator of a resonantly phase-matched line, the pump-off line against the chain matrices of its cells</td></tr><tr><td style="text-align:right;"><a href="./recipes/floquet">Floquet JTWPA</a></td><td style="text-align:right;">A tapered line, lossless and with dielectric loss, the pump-off line against the chain matrices of its cells</td></tr><tr><td style="text-align:right;"><a href="./recipes/lesa">Impedance-engineered JPA</a></td><td style="text-align:right;">A snake amplifier built from nested subcircuits, signal and idler in power units, the pump-off reflection against a closed form</td></tr><tr><td style="text-align:right;"><a href="./recipes/sensitivities">Design parameter sensitivities</a></td><td style="text-align:right;">Total and frozen-pump derivatives against finite differences, as gain derivatives</td></tr><tr><td style="text-align:right;"><a href="./recipes/scattering-sensitivities">Sensitivity to frequency dependent scattering parameters</a></td><td style="text-align:right;">The derivative of a reflection phase against the round-trip propagation phase</td></tr><tr><td style="text-align:right;"><a href="./recipes/dc">Direct current</a></td><td style="text-align:right;">Static flux and average voltage, a current source&#39;s sign, and a biased junction in time</td></tr><tr><td style="text-align:right;"><a href="./recipes/pumped-noise">Pumped finite-window noise</a></td><td style="text-align:right;">The gain and quantum noise of a pumped amplifier in a finite time window</td></tr><tr><td style="text-align:right;"><a href="./recipes/fitted-amplifier">Fit a pumped amplifier</a></td><td style="text-align:right;">A causal fit of a pumped JPA&#39;s conversion and noise, measured in time against the circuit</td></tr><tr><td style="text-align:right;"><a href="./recipes/transient-line">Pulsed Josephson line</a></td><td style="text-align:right;">Ten pulsed signals through a Josephson line in time</td></tr><tr><td style="text-align:right;"><a href="./recipes/transient-wrspice">Transient WRspice comparison</a></td><td style="text-align:right;">A JPA in time against WRspice</td></tr></tbody></table><p>The <a href="./stability">stability guide</a> works through a JPA, mode tracking across a sweep, a traveling-wave amplifier&#39;s spatial mode profile and a delay circuit, telling an operating point that converged from one that is dynamically stable. The <a href="./transient">transient guide</a> solves a circuit in time and differentiates its response, the <a href="./transientnoise">quantum noise guide</a> measures the vacuum and thermal noise of a passive two-port, and the <a href="./scattering">scattering guide</a> fits scattering data and simulates the result.</p>',4)])])}const m=e(n,[["render",s]]);export{g as __pageData,m as default};
